import { Controller } from "@hotwired/stimulus"
import { formatDateTime, formatFullDateTime } from "helpers/date_helpers"

const REFRESH_INTERVAL = 60_000 // 1 minute (in milliseconds)

// Renders the timestamp the server sent in the viewer's own timezone, so the
// same HTML reads right for everyone and stays cacheable.
export default class extends Controller {
  static values = {
    datetime: String,
    format: { type: String, default: "relative" },
    attribute: String
  }

  #timer

  connect() {
    this.render()
    if (this.#keepsUpWithTheClock) this.#timer = setInterval(() => this.render(), REFRESH_INTERVAL)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  render() {
    if (this.hasAttributeValue) {
      this.element.setAttribute(this.attributeValue, this.#formattedDateTime)
    } else {
      this.element.textContent = this.#formattedDateTime
      this.element.title = formatFullDateTime(this.#datetime)
    }
  }

  get #formattedDateTime() {
    return formatDateTime(this.#datetime, this.formatValue)
  }

  get #datetime() {
    return this.hasDatetimeValue ? this.datetimeValue : this.element.getAttribute("datetime")
  }

  get #keepsUpWithTheClock() {
    return this.formatValue === "relative"
  }
}
